-- OLAP: загрузка ресурсов.

TRUNCATE TABLE
    olap.dim_ranges,
    olap.dim_categories,
    olap.dim_products,
    olap.dim_vendors,
    olap.dim_payment_types,
    olap.dim_personnel,
    olap.dim_storages,
    olap.dim_reasons
RESTART IDENTITY;

DO $$
BEGIN
    -- единицы измерения

    -- категории товаров

    -- категории: parent_id теперь внутренний id
    UPDATE olap.dim_categories AS c
    SET parent_id = p.id
    FROM olap.dim_categories AS p
    WHERE c.parent_id = p.external_id;

    -- товары

    -- поставщики

    -- виды оплаты

    -- сотрудники

    -- склады

    -- причины списания

    -- причины списания: parent_id теперь внутренний id
    UPDATE olap.dim_reasons AS r
    SET parent_id = p.id
    FROM olap.dim_reasons AS p
    WHERE r.parent_id = p.external_id;

    -- название родительской группы
    UPDATE olap.dim_reasons AS r
    SET parent_name = p.name
    FROM olap.dim_reasons AS p
    WHERE r.parent_id = p.id;
END $$;
